# txn_store_4x1k_ch0123.S — DMA transaction timing: 4 1 KiB stores back to back on channels [0, 1, 2, 3], all waited
# CSR_DBG1 = cycles around the timed transfer only (csrrs before launch, after dma.wait).
# Generated by npu-model/scripts/gen_dma_transaction_programs.py.
# @TIMEOUT 100000
# @DRAM_BASE 0x90000000
# @PERF_REPORT

    li    x5, 0x00000000
    dma.config x5, ch0
    dma.config x5, ch1
    dma.config x5, ch2
    dma.config x5, ch3
    li    x12, 32
    li    x13, 1024
    li    x14, 4096
    csrrs x20, 0xC00, x0        # cycle count at launch
    addi  x6, x0, 0
    li    x10, 0x90100000
    dma.store x10, x6, x13, ch0
    addi  x6, x0, 256
    li    x10, 0x90101000
    dma.store x10, x6, x13, ch1
    addi  x6, x0, 512
    li    x10, 0x90102000
    dma.store x10, x6, x13, ch2
    addi  x6, x0, 768
    li    x10, 0x90103000
    dma.store x10, x6, x13, ch3
    dma.wait  ch0
    dma.wait  ch1
    dma.wait  ch2
    dma.wait  ch3
    csrrs x21, 0xC00, x0        # cycle count after completion
    sub   x22, x21, x20
    csrrw x0,  0xC11, x22       # CSR_DBG1
    addi  x30, x0, 1
    csrrw x0, 0xC10, x30
    ecall
